import sqlite3, json, os, glob
from datetime import datetime, timezone

DB="/home/jinsc/.zcode/cli/db/db.sqlite"
OUT="/tmp/vela-log-staging"
LOGS="/home/jinsc/esp/Desktop/vela/contest2026_048_dijiugexiaxianyue/logs/jinsc123654"
SKIP={"system_reminder","background_notification","compact_summary","subagent_notification"}
PREF=("/home/jinsc/SDK/vela/","/home/jinsc/esp/Desktop/vela/","/home/jinsc/Desktop_My/work/my_work/sifli/")

def iso(ms):
    return datetime.fromtimestamp(ms/1000, tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.")+f"{int(ms)%1000:03d}Z"

committed=set()
for f in glob.glob(os.path.join(LOGS,"*","*.jsonl")):
    committed.add(os.path.basename(f).split("__",1)[1][:-len(".jsonl")])

con=sqlite3.connect(f"file:{DB}?mode=ro",uri=True)
def records(sid):
    seq=0
    for mid,mtime,mdata in con.execute("select id,time_created,data from message where session_id=? order by sequence",(sid,)).fetchall():
        m=json.loads(mdata); sem=m.get("semantics") or {}
        if (sem.get("kind") or "") in SKIP: continue
        role=m.get("role"); model=m.get("modelId"); tok=m.get("tokens") or {}
        turn=(m.get("anchor") or {}).get("turnId"); first=True
        parts=con.execute("select time_created,sequence,data from part where message_id=? order by time_created,sequence",(mid,)).fetchall()
        for ptime,_ps,pdata in parts:
            p=json.loads(pdata); t=p.get("type")
            rec={"seq":None,"timestamp":iso(ptime or mtime),"role":role,"text":None,"thinking":None,
                 "tool_name":None,"input":None,"output":None,"model":model,"tokens_in":None,"tokens_out":None,
                 "session_id":sid,"turn_id":turn}
            if t=="text": rec["text"]=p.get("text")
            elif t=="reasoning": rec["thinking"]=p.get("text")
            elif t=="tool":
                st=p.get("state") or {}
                rec["tool_name"]=p.get("tool")
                inp=st.get("input"); rec["input"]=None if inp is None else json.dumps(inp,ensure_ascii=False)
                out=st.get("output"); rec["output"]=out if out is not None else st.get("error")
            else: continue
            if first:
                if role=="assistant":
                    rec["tokens_in"]=tok.get("input"); rec["tokens_out"]=tok.get("output")
                first=False
            seq+=1; rec["seq"]=seq
            yield rec

stats=[]
for sid,dirn,pid,tc in con.execute("select id,directory,parent_id,time_created from session order by time_created").fetchall():
    if not dirn.startswith(PREF) or sid in committed: continue
    day=datetime.fromtimestamp(tc/1000,tz=timezone.utc).strftime("%Y-%m-%d")
    d=os.path.join(OUT,day); os.makedirs(d,exist_ok=True)
    path=os.path.join(d,f"zcode__{sid}.jsonl")
    n=0
    with open(path,"w",encoding="utf-8") as f:
        for rec in records(sid):
            f.write(json.dumps(rec,ensure_ascii=False)+"\n"); n+=1
    stats.append((sid,day,n,os.path.getsize(path),bool(pid),dirn))

print(f"exported {len(stats)} sessions, {sum(s[2] for s in stats)} events, {sum(s[3] for s in stats)/1e6:.1f} MB")
with open("/tmp/vela-log-staging/stats.csv","w",encoding="utf-8") as f:
    f.write("session_id,date,events,bytes,is_subagent,directory\n")
    for s in stats: f.write(f'{s[0]},{s[1]},{s[2]},{s[3]},{int(s[4])},"{s[5]}"\n')
print("largest:")
for s in sorted(stats,key=lambda x:-x[3])[:5]: print(f"  {s[3]/1e6:7.2f} MB  {s[2]:6d} ev  {s[0]}")
